import {designContextHTML} from './design-context.mjs?v=0.8.0';
import {DESIGN_FIELDS,DESIGN_CATEGORIES,designProfile,validateDesign,applyDesign,rule} from './design-rules.mjs?v=0.8.0';
const number=n=>new Intl.NumberFormat('fr-CA',{maximumFractionDigits:5}).format(n);
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function mountDesignDashboard(root,{world,onApply}) {
 let owner,applied,draft={},search='',category='formation',modified=false;
 root.innerHTML=`<div class="design-heading"><div><div class="section-head">ATELIER D’ÉQUILIBRAGE</div><h2>Les règles de ta partie</h2><p>Prépare tes changements, puis applique-les ensemble. Ils sont conservés dans la sauvegarde de ce monde.</p></div><a href="./docs/gdd/equilibrage.html" target="_blank" rel="noopener">Guide des paramètres ↗</a></div><div class="design-toolbar"><label>Rechercher<input type="search" data-design-search placeholder="Affinité, répétition, énergie…"></label><label>Système<select data-design-category><option value="">Tous les systèmes</option>${Object.entries(DESIGN_CATEGORIES).map(([key,name])=>`<option value="${key}">${name}</option>`).join('')}</select></label><label class="design-check"><input type="checkbox" data-design-modified> Valeurs personnalisées</label></div><p class="muted">Probabilités : 0,315 = 31,5 %. Durées en minutes de jeu. Les échéances déjà programmées ne sont pas recalculées. Les multiplicateurs généraux ci-dessous restent actifs et ne font pas partie de ce profil.</p><div class="design-summary" aria-live="polite"></div><div class="design-fields"></div><div class="design-footer"><div class="inline-actions"><button class="primary" data-design-apply>Appliquer les changements</button><button data-design-cancel>Annuler les modifications</button><button data-design-reset>Préparer les valeurs par défaut</button></div><div class="inline-actions"><button data-design-export>Exporter le profil</button><button data-design-import>Importer un profil</button><input type="file" data-design-file accept=".json,application/json" hidden></div><p data-design-status role="status">Aucun changement en attente.</p></div>`;
 const fields=root.querySelector('.design-fields'),status=root.querySelector('[data-design-status]');
 root.querySelector('[data-design-category]').value=category;
 root.insertBefore(root.querySelector('.design-footer'),fields);
 const value=(s,f)=>s[f.id]??f.default;
 const committed=()=>world().design?.values||{};
 function summary(){const changed=DESIGN_FIELDS.filter(f=>value(draft,f)!==rule(world(),f.id)).length,custom=DESIGN_FIELDS.filter(f=>value(draft,f)!==f.default).length;
 root.querySelector('.design-summary').textContent=`${DESIGN_FIELDS.length} paramètres branchés · ${custom} personnalisé${custom===1?'':'s'} · ${changed} changement${changed===1?'':'s'} en attente`;
 root.querySelector('[data-design-apply]').disabled=changed===0;root.querySelector('[data-design-cancel]').disabled=changed===0;
 }
 function render(){fields.innerHTML=Object.entries(DESIGN_CATEGORIES).map(([key,label])=>{
 const rows=DESIGN_FIELDS.filter(f=>f.category===key&&(!category||category===key)&&(!modified||value(draft,f)!==f.default)&&normalize(f.label+' '+f.description+' '+f.id+' '+label).includes(normalize(search)));
 return rows.length?`<section class="design-section"><h3>${label}<span>${rows.length}</span></h3>${rows.map(f=>`<div class="design-row ${value(draft,f)!==f.default?'is-custom':''}" data-design-row="${f.id}"><div><label for="design-${f.id}">${f.label}</label><p>${f.description}</p><small>Référence : ${number(f.default)} ${f.unit} · En jeu : <b>${number(rule(world(),f.id))}</b></small><details class="design-context" data-design-context="${f.id}"><summary>Comprendre le calcul et ses conditions</summary><div>${designContextHTML(f.id,world(),draft)}</div></details></div><div class="design-value"><input id="design-${f.id}" data-design-value="${f.id}" type="number" min="${f.min}" max="${f.max}" step="any" value="${value(draft,f)}" aria-describedby="bounds-${f.id}"><span>${f.unit}</span><small id="bounds-${f.id}">${number(f.min)} à ${number(f.max)}${f.step===1?' · entier':''}</small><button data-design-default="${f.id}" title="Préparer la valeur de référence">Réinitialiser</button></div></div>`).join('')}</section>`:'';
 }).join('')||'<p class="design-empty">Aucun paramètre ne correspond à ces filtres.</p>';summary();}
 function sync(){const s=world();if(owner!==s||applied!==s.design){owner=s;applied=s.design;draft={...committed()};status.textContent='Profil de cette partie chargé.';render();}}
 root.addEventListener('input',e=>{if(e.target.matches('[data-design-search]')){search=e.target.value;if(search){category='';root.querySelector('[data-design-category]').value='';}render();}
 const id=e.target.dataset.designValue;if(id){draft[id]=e.target.value===''?NaN:Number(e.target.value);summary();for(const details of fields.querySelectorAll('[data-design-context]'))details.querySelector('div').innerHTML=designContextHTML(details.dataset.designContext,world(),draft);e.target.closest('.design-row').classList.toggle('is-custom',draft[id]!==DESIGN_FIELDS.find(f=>f.id===id).default);status.textContent='Changements en attente : applique-les pour modifier le jeu.';}});
 root.addEventListener('change',async e=>{if(e.target.matches('[data-design-category]')){category=e.target.value;render();}if(e.target.matches('[data-design-modified]')){modified=e.target.checked;render();}
 if(e.target.matches('[data-design-file]')){try{const file=e.target.files[0];if(!file)return;if(file.size>256000)throw Error('Profil trop volumineux (maximum 256 Ko).');const profile=JSON.parse(await file.text());validateDesign(profile);if(!profile)throw Error('Profil manquant.');draft={...profile.values};render();status.textContent='Profil importé en préparation. Vérifie les valeurs, puis applique-les.';}catch(error){status.textContent='Import refusé : '+error.message;}finally{e.target.value='';}}});
 root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;try{
 const id=button.dataset.designDefault;if(id){delete draft[id];render();status.textContent='Valeur de référence préparée ; applique les changements.';}
 if(button.hasAttribute('data-design-cancel')){draft={...committed()};render();status.textContent='Modifications annulées.';}
 if(button.hasAttribute('data-design-reset')){draft={};render();status.textContent='Valeurs par défaut préparées. Rien ne change avant application.';}
 if(button.hasAttribute('data-design-import'))root.querySelector('[data-design-file]').click();
 if(button.hasAttribute('data-design-export')){const profile=designProfile(draft),url=URL.createObjectURL(new Blob([JSON.stringify(profile,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='garage-vivant-equilibrage.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Profil préparé exporté. La partie n’a pas été modifiée.';}
 if(button.hasAttribute('data-design-apply')){const s=world();if(s.performance?.status==='playing'||s.showEventId)throw Error('Termine le spectacle en cours avant de changer l’équilibrage.');const profile=designProfile(draft),changes=DESIGN_FIELDS.filter(f=>value(draft,f)!==rule(s,f.id)).map(f=>({id:f.id,before:rule(s,f.id),after:value(draft,f)}));if(!changes.length)return;applyDesign(s,profile);applied=s.design;draft={...profile.values};onApply(changes);render();status.textContent=`${changes.length} changement${changes.length===1?'':'s'} appliqué${changes.length===1?'':'s'} à cette partie. Les prochaines évaluations utilisent ces valeurs.`;}
 }catch(error){status.textContent='Changement refusé : '+error.message;}});
 sync();return {sync};
}
